{
  "findings": [
    {
      "ref": "[D538]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child, and this can be turned off.",
      "stance": "risk",
      "quote": "Some users may encourage children to continue conversations on other platforms such as Discord, Snapchat, Instagram or WhatsApp."
    },
    {
      "ref": "[D538]",
      "area": "contact",
      "claim": "Voice chat on Roblox can increase the risk of children hearing inappropriate language, being contacted by strangers or sharing personal information.",
      "stance": "risk",
      "quote": "Some Roblox experiences include voice chat, allowing players to speak with each other in real time rather than using text messages. While this can make gameplay more social and immersive, it can also increase the risk of children hearing inappropriate language, being contacted by strangers or sharing personal information without thinking."
    },
    {
      "ref": "[D538]",
      "area": "money",
      "claim": "Roblox pushes in-app purchases and scams that promise free Robux, which can steal account details or personal information.",
      "stance": "risk",
      "quote": "Many scams on Roblox promise free Robux, exclusive items or special rewards. These offers often aim to collect account details or personal information. Encourage children to avoid clicking unfamiliar links and remind them that if an offer seems too good to be true, it probably is."
    },
    {
      "ref": "[D538]",
      "area": "data",
      "claim": "Roblox collects user data and may share it with third parties, and the data can be deleted.",
      "stance": "neutral",
      "quote": "Roblox uses Content Maturity Labels on all content on the platform."
    },
    {
      "ref": "[D538]",
      "area": "age_gating",
      "claim": "Roblox does not have a single minimum age, but uses content maturity labels and age verification to restrict access to certain experiences.",
      "stance": "mitigation",
      "quote": "Some Roblox features and experiences require users to verify their age before they can access them. This is designed to help prevent younger users from accessing content intended for older teens and adults."
    },
    {
      "ref": "[D538]",
      "area": "content",
      "claim": "A 10-year-old was able to access highly suggestive spaces with sexual undertones on Roblox.",
      "stance": "risk",
      "quote": "Exploring as the 10-year-old, the team was able to access “highly suggestive” spaces. These included games featuring hotels with private rooms and characters dressed in “sexually suggestive outfits.”"
    },
    {
      "ref": "[D538]",
      "area": "developer_record",
      "claim": "Roblox has been fined or faced regulatory action for failing to protect children from inappropriate content.",
      "stance": "risk",
      "quote": "An April 2025 report from Revealing Reality highlighted “suggestive behaviours” among other concerns. The research team created Roblox accounts for 5-, 9-, 10-, 13- and 42-year-olds to test the interactions of different users based on their age."
    }
  ]
}
